content:
@keyframes shimmer {
  from { opacity: 1; }
  to { opacity: 0.5; }
}

@layer components {
  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    animation-name: shimmer;
  }
}

@layer components {
  @keyframes shimmer {
    from { opacity: 1; }
    to { opacity: 0.5; }
  }

  .book-card {
    border-radius: var(--shelf-radius-md);
    background-color: var(--shelf-bgColor-raised);
    animation-name: shimmer;
  }
}

@keyframes token-pulse {
  from { opacity: 1; }
  to { opacity: 0.6; }
}

@layer tokens {
  :root {
    --shelf-bgColor-default: hsl(30 15% 97%);
  }
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  @keyframes slide-in {
    from { transform: translateX(100%); }
    to { transform: translateX(0); }
  }

  @keyframes slide-out {
    from { transform: translateX(0); }
    to { transform: translateX(100%); }
  }

  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
  }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@layer components {
  @keyframes stagger {
    from { transform: translateY(var(--shelf-space-sm)); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
  }

  .shelf-grid {
    display: grid;
    gap: var(--shelf-space-md);
  }
}

@layer components {
  .chip-bar {
    display: flex;
    gap: var(--shelf-space-sm);
    padding: var(--shelf-space-sm) var(--shelf-space-md);
  }

  .chip {
    display: inline-flex;
    align-items: center;
    border-radius: var(--shelf-radius-full);
  }
}
